"use client";
/* Cherries, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Cherries(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("cherries"); }, []);
  return React.createElement("piix-sprite", { "name": "cherries", ...piixAttrs(props) });
}

export default Cherries;
